function apply(){const purpose=document.querySelector('.pond-purpose');if(!purpose)return;if(!document.querySelector('.photo-story')){const photos=document.createElement('section');photos.className='photo-story';photos.id='photo-preview';photos.setAttribute('aria-label','Dancing and cuddling with dogs');photos.innerHTML='';purpose.before(photos);if(location.hash==='#photo-preview')photos.scrollIntoView()}if(!document.querySelector('.preview-statement')){const heading=document.querySelector('#belief');const photoStory=document.querySelector('.photo-story');if(photoStory&&!photoStory.querySelector('.cutout-composition')){const cutouts=document.createElement('div');cutouts.className='cutout-composition';cutouts.innerHTML="<div class=\"cutout-person dancing-cutout\"><img src=\"/assets/approved-homepage/simon-cutout.png\" alt=\"Simon dancing, with the background removed\"><span class=\"cutout-ink\">dancing</span><svg viewBox=\"0 0 100 150\" aria-hidden=\"true\"><path d=\"M15 135 Q12 65 73 22 M54 26 L76 18 L74 42\"/></svg></div><div class=\"cutout-person dog-cutout\"><img src=\"/assets/approved-homepage/olivia-dog-cutout.png\" alt=\"Olivia cuddling her dog, with her clothes preserved and the background removed\"><span class=\"cutout-ink\">cuddling<br>with dogs</span><svg viewBox=\"0 0 120 100\" aria-hidden=\"true\"><path d=\"M20 15 Q78 5 85 74 M70 60 L86 78 L96 59\"/></svg></div>";photoStory.prepend(cutouts)}
const story=document.querySelector('.photo-story');if(heading&&story){const statement=document.createElement('section');statement.className='preview-statement';statement.id='statement-preview';statement.setAttribute('aria-label','What we believe');const copy=heading.cloneNode(true);copy.removeAttribute('id');statement.append(copy);story.before(statement)}}
const story=document.querySelector('.photo-story');if(story&&!story.querySelector('.photo-caption')){const note=document.createElement('div');note.className='photo-caption';note.innerHTML='<span>us having fun</span><svg viewBox="0 0 260 60" aria-hidden="true"><path d="M18 39 C80 43 163 40 236 38"/></svg>';story.append(note)}
const jump=document.querySelector('#make-room');if(jump&&!jump.dataset.previewJump){jump.dataset.previewJump='1';jump.addEventListener('click',event=>{event.stopImmediatePropagation();const scene=document.querySelector('.belief-pond .scene'),study=document.querySelector('#study'),frog=scene.querySelector('.newcomer'),hug=scene.querySelector('.hug');if(study.dataset.state==='moving')return;if(study.dataset.state==='hugged'){study.dataset.state='idle';frog.style.opacity='';hug.style.opacity='';jump.textContent='Me too';return}study.dataset.state='moving';jump.textContent='Jumping…';jump.setAttribute('aria-disabled','true');frog.dataset.pose='air';const distance=scene.clientWidth-(innerWidth<600?110:150)-frog.offsetLeft;const arc=innerWidth<600?120:165;const keyframes=Array.from({length:17},(_,i)=>{const t=i/16;return {transform:`translate(${distance*t}px,${-Math.sin(Math.PI*t)*arc}px) rotate(${Math.sin(Math.PI*2*t)*8}deg)`,offset:t}});const animation=frog.animate(keyframes,{duration:1500,easing:'linear',fill:'forwards'});animation.finished.then(()=>{animation.cancel();frog.style.opacity='0';study.dataset.state='hugged';hug.style.opacity='1';jump.textContent='Again';jump.removeAttribute('aria-disabled');scene.setAttribute('aria-label','Three frogs together at the lower right.');});},true)}
const social=document.querySelector('dialog[data-dialog="social"]');if(social&&!social.dataset.rudePreview){social.dataset.rudePreview='1';const olivia=social.querySelector('a[href*="olivia"]'),simon=social.querySelector('a[href*="simon"]');if(olivia&&simon){const bubble=document.createElement('span');bubble.className='rude-bubble';bubble.innerHTML='<svg viewBox="0 0 130 64" aria-hidden="true"><path d="M30 15 L3 9 Q10 20 20 27 C11 42 30 56 62 56 C105 59 139 39 118 18 C101 3 56 2 30 15 Z"/></svg><span>rude</span>';bubble.hidden=true;bubble.setAttribute('role','status');olivia.parentElement.classList.add('olivia-speech');olivia.after(bubble);simon.addEventListener('click',event=>{if(simon.dataset.ready==='yes'){bubble.hidden=true;delete simon.dataset.ready;return}event.preventDefault();event.stopImmediatePropagation();simon.dataset.ready='yes';bubble.hidden=false;},true);social.addEventListener('close',()=>{bubble.hidden=true;delete simon.dataset.ready});}}
const footerHeading=document.querySelector('#footer-heading');if(footerHeading&&!footerHeading.dataset.revisedCopy){footerHeading.dataset.revisedCopy='1';footerHeading.innerHTML='We made this.<br>Show us what you can do.'}const btn=document.querySelector('.footer-try');if(btn&&!btn.dataset.preview){btn.dataset.preview='1';btn.innerHTML='<span class="try-label">Try</span><img src="/apparent-wordmark.svg" alt="apparent"><span class="try-arrow" aria-hidden="true">↗</span>'}}
window.addEventListener('load',()=>setTimeout(()=>{apply();new MutationObserver(apply).observe(document.documentElement,{subtree:true,childList:true});},200));
